function validate([responses]) {
  if (responses.length < 1 || responses.length > 1000) return 'responses needs 1 to 1000 days.';
  for (const day of responses) {
    if (day.length < 1 || day.length > 1000) return 'Each day has 1 to 1000 responses.';
    if (day.some(word => !/^[a-z]{1,10}$/.test(word))) return 'Each response is 1 to 10 lowercase letters.';
  }
  return null;
}

