function findCommonResponse(responses) {
  const count = new Map();
  for (const day of responses) {
    for (const response of new Set(day)) {
      count.set(response, (count.get(response) ?? 0) + 1);
    }
  }
  let best = '';
  let bestCount = 0;
  for (const [response, days] of count) {
    if (days > bestCount || (days === bestCount && response < best)) {
      best = response;
      bestCount = days;
    }
  }
  return best;
}

