function findCommonResponse(responses) {
  // Score every distinct word by the number of day lists containing it, then sort by score and spelling.
  const words = [...new Set(responses.flat())];
  const scored = words.map(word => [responses.filter(day => day.includes(word)).length, word]);
  scored.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? -1 : 1));
  return scored[0][1];
}

