function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const word = (letters, longest) => {
    const length = 1 + Math.floor(rand() * longest);
    let text = '';
    for (let i = 0; i < length; i++) text += pick(letters);
    return text;
  };
  if (size === 'large') {
    // Either many short days or a few long ones; a small vocabulary makes ties likely.
    const manyDays = rand() < 0.5;
    const pool = Array.from({ length: pick([5, 40, 400]) }, () => word('abcdefghijklmnopqrstuvwxyz', 10));
    const dayLength = () => manyDays ? 1 + Math.floor(rand() * 15) : 700 + Math.floor(rand() * 301);
    return [Array.from({ length: manyDays ? 1000 : 12 }, () => Array.from({ length: dayLength() }, () => pick(pool)))];
  }
  // Short words over two letters, so equal counts and prefixes such as "a" and "ab" are common.
  const pool = Array.from({ length: 1 + Math.floor(rand() * 5) }, () => word('ab', 3));
  const days = 1 + Math.floor(rand() * 5);
  return [Array.from({ length: days }, () => Array.from({ length: 1 + Math.floor(rand() * 6) }, () => pick(pool)))];
}
